INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_06','V520','工作人员',6,'流程一致，加急通道三个工作日可取证。','liú chéng yí zhì， jiā jí tōng dào sān gè gōng zuò rì kě qǔ zhèng。','Quy trình giống nhau, nhưng đi kênh nhanh thì ba ngày làm việc là lấy được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_07','V520','阮明',7,'补办的居留有效期和原来丢失的证件剩余时长相同吧？','bǔ bàn de jū liú yǒu xiào qī hé yuán lái diū shī de zhèng jiàn shèng yú shí cháng xiāng tóng ba？','Thời hạn tạm trú làm lại có bằng đúng thời gian còn lại của thẻ cũ bị mất không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_08','V520','工作人员',8,'完全同步原有到期日期，不会重新计算一年有效期。','wán quán tóng bù yuán yǒu dào qī rì qī， bú huì chóng xīn jì suàn yī nián yǒu xiào qī。','Hoàn toàn khớp với ngày hết hạn cũ, chứ không tính lại một năm từ đầu đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_09','V520','阮明',9,'全部材料齐全，麻烦受理我的补办申请。','quán bù cái liào qí quán， má fán shòu lǐ wǒ de bǔ bàn shēn qǐng。','Hồ sơ tôi chuẩn bị đầy đủ hết rồi, phiền anh tiếp nhận giúp yêu cầu làm lại của tôi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT521','SV3','出境紧急情况无证件，申请出入境临时通行纸',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V521','SIT521','P1','twist','chinh_thuc',NULL,'临时出入境通行证明仅限单次出境，不可用于再次入境中国，回国后需在本国驻华使馆补办正式护照。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_01','V521','阮明',1,'警官，我明天一早航班回国，护照丢失急需临时通行证件。','jǐng guān， wǒ míng tiān yī zǎo háng bān huí guó， hù zhào diū shī jí xū lín shí tōng xíng zhèng jiàn。','Anh ơi, sáng mai tôi bay về nước rồi, hộ chiếu bị mất nên cần gấp giấy thông hành tạm thời.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_02','V521','民警',2,'先出示派出所遗失回执，我核对你的全部备案信息。','xiān chū shì pài chū suǒ yí shī huí zhí， wǒ hé duì nǐ de quán bù bèi àn xìn xī。','Anh đưa biên nhận trình báo mất của công an trước, tôi kiểm tra lại toàn bộ thông tin đăng ký của anh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_03','V521','阮明',3,'回执随身携带，但是今天自助拍照机已经停止营业了嘛。','huí zhí suí shēn xié dài， dàn shì jīn tiān zì zhù pāi zhào jī yǐ jīng tíng zhǐ yíng yè le ma。','Biên nhận tôi mang theo đây, nhưng hôm nay máy chụp ảnh tự động đã ngừng hoạt động rồi ạ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_04','V521','民警',4,'紧急出境可免纸质照片，系统调取之前留存的证件照片。','jǐn jí chū jìng kě miǎn zhǐ zhì zhào piān， xì tǒng diào qǔ zhī qián liú cún de zhèng jiàn zhào piān。','Trường hợp xuất cảnh khẩn cấp thì được miễn ảnh giấy, hệ thống sẽ lấy lại ảnh giấy tờ đã lưu trước đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_05','V521','阮明',5,'这份临时通行纸只能用于本次出境，不能再次入境国内对吗？','zhè fèn lín shí tōng xíng zhǐ zhǐ néng yòng yú běn cì chū jìng， bù néng zài cì rù jìng guó nèi duì ma？','Giấy thông hành tạm thời này chỉ dùng để xuất cảnh lần này thôi, không thể dùng để nhập cảnh lại được đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_06','V521','民警',6,'单次出境有效，抵达越南后前往使馆办理新护照。','dān cì chū jìng yǒu xiào， dǐ dá yuè nán hòu qián wǎng shǐ guǎn bàn lǐ xīn hù zhào。','Chỉ có hiệu lực xuất cảnh một lần, về đến Việt Nam thì anh ra đại sứ quán làm hộ chiếu mới.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_07','V521','阮明',7,'办理完成当场就能领取通行纸质证明，不用等候工作日？','bàn lǐ wán chéng dāng chǎng jiù néng lǐng qǔ tōng xíng zhǐ zhì zhèng míng， bù yòng děng hòu gōng zuò rì？','Làm xong là lấy được giấy thông hành ngay tại chỗ luôn, không cần chờ ngày làm việc đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_08','V521','民警',8,'紧急出境业务当场办结，十分钟打印完成交付本人。','jǐn jí chū jìng yè wù dāng chǎng bàn jié， shí fēn zhōng dǎ yìn wán chéng jiāo fù běn rén。','Nghiệp vụ xuất cảnh khẩn cấp giải quyết ngay tại chỗ, mười phút là in xong giao tận tay anh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_09','V521','阮明',9,'太感谢开通紧急通道，不然我明天无法搭乘航班。','tài gǎn xiè kāi tōng jǐn jí tōng dào， bù rán wǒ míng tiān wú fǎ dā chéng háng bān。','Cảm ơn anh nhiều vì đã mở kênh khẩn cấp, không thì mai tôi lỡ chuyến bay mất.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT522','SV3','居留卡片丢失，线上挂失后线下补办',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V522','SIT522','P1','suon_se','tuy_y',NULL,'外国人居留卡丢失需线上立即挂失，挂失后原卡直接作废，无法恢复使用，只能线下重新制卡。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_01','V522','阮明',1,'你好，我的外国人居留卡片弄丢了，怎么挂失补办？','nǐ hǎo， wǒ de wài guó rén jū liú kǎ piàn nòng diū le， zěn me guà shī bǔ bàn？','Chào bạn, thẻ tạm trú người nước ngoài của mình bị mất rồi, phải báo mất rồi làm lại thế nào vậy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_02','V522','引导员',2,'先在出入境官方小程序线上挂失锁卡，防止他人冒用哦。','xiān zài chū rù jìng guān fāng xiǎo chéng xù xiàn shàng guà shī suǒ kǎ， fáng zhǐ tā rén mào yòng ó。','Bạn báo mất khóa thẻ trên app xuất nhập cảnh chính thức trước đã nhé, để tránh người khác lợi dụng.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_03','V522','阮明',3,'线上挂失完成，再带什么材料线下补办实体卡片？','xiàn shàng guà shī wán chéng， zài dài shén me cái liào xiàn xià bǔ bàn shí tǐ kǎ piàn？','Báo mất online xong rồi, vậy cần mang thêm giấy tờ gì để làm lại thẻ cứng trực tiếp vậy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_04','V522','引导员',4,'白底证件照、护照、在读证明、住宿登记单四样材料。','bái dǐ zhèng jiàn zhào、 hù zhào、 zài dú zhèng míng、 zhù sù dēng jì dān sì yàng cái liào。','Bốn thứ thôi: ảnh nền trắng, hộ chiếu, giấy xác nhận đang học, và phiếu đăng ký tạm trú.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_05','V522','阮明',5,'挂失之后如果捡到卡片，还能解除挂失继续使用吗？','guà shī zhī hòu rú guǒ jiǎn dào kǎ piàn， hái néng jiě chú guà shī jì xù shǐ yòng ma？','Sau khi báo mất mà lỡ tìm lại được thẻ thì có hủy báo mất để dùng tiếp được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_06','V522','引导员',6,'挂失后卡片永久失效，无论找回都必须重新补办。','guà shī hòu kǎ piàn yǒng jiǔ shī xiào， wú lùn zhǎo huí dōu bì xū chóng xīn bǔ bàn。','Báo mất xong là thẻ vô hiệu vĩnh viễn luôn, có tìm lại cũng phải làm lại thẻ mới thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_07','V522','阮明',7,'挂失操作我现在手机完成，之后取号递交补办材料。','guà shī cāo zuò wǒ xiàn zài shǒu jī wán chéng， zhī hòu qǔ hào dì jiāo bǔ bàn cái liào。','Vậy mình thao tác báo mất trên điện thoại luôn bây giờ, xong quay lại lấy số nộp hồ sơ làm lại.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT523','SV3','旧护照签证页剪角，咨询新旧护照联用规则',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V523','SIT523','P1','twist','ban_chinh_thuc',NULL,'旧护照到期剪角，居留贴纸短期可新旧护照联用，缓冲期三十天，超时无法正常出入境，必须转移居留许可至新护照。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_01','V523','阮明',1,'警官，我的旧护照到期剪角换新，居留贴纸还在旧护照上。','jǐng guān， wǒ de jiù hù zhào dào qī jiǎn jiǎo huàn xīn， jū liú tiē zhǐ hái zài jiù hù zhào shàng。','Anh ơi, hộ chiếu cũ của tôi hết hạn nên cắt góc đổi hộ chiếu mới, nhưng tem tạm trú vẫn còn ở hộ chiếu cũ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_02','V523','辅警',2,'短期出入境可以新旧两本护照一并出示海关查验呢。','duǎn qī chū rù jìng kě yǐ xīn jiù liǎng běn hù zhào yī bìng chū shì hǎi guān chá yàn ne。','Xuất nhập cảnh ngắn ngày thì có thể xuất trình cả hai cuốn hộ chiếu cũ và mới cho hải quan kiểm tra cùng lúc đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_03','V523','阮明',3,'新旧护照联用有时间限制，不能长期一直这样使用吗？','xīn jiù hù zhào lián yòng yǒu shí jiān xiàn zhì， bù néng cháng qī yì zhí zhè yàng shǐ yòng ma？','Việc dùng chung hai hộ chiếu có giới hạn thời gian, không thể cứ để vậy dùng lâu dài được đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_04','V523','辅警',4,'联用仅允许三十天缓冲期，超期必须转移居留至新护照嘛。','lián yòng jǐn yǔn xǔ sān shí tiān huǎn chōng qī， chāo qī bì xū zhuǎn yí jū liú zhì xīn hù zhào ma。','Chỉ được dùng chung trong thời gian đệm ba mươi ngày thôi, quá hạn là bắt buộc phải chuyển tạm trú sang hộ chiếu mới.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_05','V523','阮明',5,'转移居留贴纸需要单独预约换发业务，还是续签同步办理？','zhuǎn yí jū liú tiē zhǐ xū yào dān dú yù yuē huàn fā yè wù， hái shì xù qiān tóng bù bàn lǐ？','Chuyển tem tạm trú thì phải đặt lịch riêng cho việc cấp lại, hay là làm cùng lúc với gia hạn visa vậy anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_06','V523','辅警',6,'单独预约居留信息变更业务，无需等到签证到期。','dān dú yù yuē jū liú xìn xī biàn gēng yè wù， wú xū děng dào qiān zhèng dào qī。','Đặt lịch riêng cho việc thay đổi thông tin tạm trú, không cần đợi đến khi visa hết hạn đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_07','V523','阮明',7,'那我三天内预约窗口，把居留贴纸转移到新护照上。','nà wǒ sān tiān nèi yù yuē chuāng kǒu， bǎ jū liú tiē zhǐ zhuǎn yí dào xīn hù zhào shàng。','Vậy trong ba ngày tới tôi sẽ đặt lịch, để chuyển tem tạm trú sang hộ chiếu mới.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT524','SV4','校内转专业，办理居留许可信息变更',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V524','SIT524','P1','suon_se','ban_chinh_thuc',NULL,'留学生校内转专业、更换学院，必须三十日内到出入境更新居留证件信息，信息不符会被判定证件失效。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_01','V524','阮明',1,'您好，我校内转换专业，来办理居留证件信息变更。','nín hǎo， wǒ xiào nèi zhuǎn huàn zhuān yè， lái bàn lǐ jū liú zhèng jiàn xìn xī biàn gēng。','Chào chị, tôi vừa chuyển ngành học trong trường, đến để làm thay đổi thông tin trên giấy tạm trú.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_02','V524','工作人员',2,'递交新专业录取调整证明、护照、白底证件照。','dì jiāo xīn zhuān yè lù qǔ tiáo zhěng zhèng míng、 hù zhào、 bái dǐ zhèng jiàn zhào。','Anh nộp giấy xác nhận điều chỉnh ngành học mới, hộ chiếu, và ảnh nền trắng nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_03','V524','阮明',3,'只是专业变更，居留到期日会不会同步延后调整？','zhǐ shì zhuān yè biàn gēng， jū liú dào qī rì huì bú huì tóng bù yán hòu tiáo zhěng？','Chỉ đổi ngành học thôi thì ngày hết hạn tạm trú có bị lùi lại theo không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_04','V524','工作人员',4,'到期日期不变，仅更新证件上标注的就读专业。','dào qī rì qī bù biàn， jǐn gēng xīn zhèng jiàn shàng biāo zhù de jiù dú zhuān yè。','Ngày hết hạn không đổi đâu, chỉ cập nhật lại ngành học ghi trên giấy tờ thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_05','V524','阮明',5,'变更业务办理时长多久，当天可以取证吗？','biàn gēng yè wù bàn lǐ shí cháng duō jiǔ， dàng tiān kě yǐ qǔ zhèng ma？','Thủ tục thay đổi này mất bao lâu vậy chị, hôm nay có lấy được luôn không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_06','V524','工作人员',6,'三个工作日办结，不能当场领取变更后的居留卡。','sān gè gōng zuò rì bàn jié， bù néng dāng chǎng lǐng qǔ biàn gēng hòu de jū liú kǎ。','Ba ngày làm việc là xong, không thể lấy thẻ tạm trú đã cập nhật ngay tại chỗ đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_07','V524','阮明',7,'信息变更不收取额外手续费，只需要提交材料对吧？','xìn xī biàn gēng bù shōu qǔ é wài shǒu xù fèi， zhǐ xū yào tí jiāo cái liào duì ba？','Thay đổi thông tin không thu thêm phí gì, chỉ cần nộp hồ sơ thôi đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_08','V524','工作人员',8,'校内专业变更属于免费业务，无任何工本费。','xiào nèi zhuān yè biàn gēng shǔ yú miǎn fèi yè wù， wú rèn hé gōng běn fèi。','Chuyển ngành học trong trường là nghiệp vụ miễn phí, không có phí làm hồ sơ nào cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_09','V524','阮明',9,'材料全部备好，麻烦受理信息变更申请。','cái liào quán bù bèi hǎo， má fán shòu lǐ xìn xī biàn gēng shēn qǐng。','Hồ sơ tôi chuẩn bị đầy đủ hết rồi, phiền chị tiếp nhận giúp yêu cầu thay đổi thông tin của tôi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT525','SV4','从A校转学至另一城市高校，办理居留迁出迁入',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V525','SIT525','P1','twist','chinh_thuc',NULL,'跨城市转学居留无法异地转移，原城市居留注销失效，抵达新城市三十日内必须重新申请本地学生居留许可。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_01','V525','阮明',1,'老师，我转学去另一城市大学，咨询居留迁出流程。','lǎo shī， wǒ zhuǎn xué qù lìng yī chéng shì dà xué， zī xún jū liú qiān chū liú chéng。','Thưa thầy/cô, em chuyển trường sang đại học ở thành phố khác, muốn hỏi về thủ tục chuyển đi cư trú ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_02','V525','老师',2,'先开具转学离校证明，再去本地出入境办理居留迁出备案。','xiān kāi jù zhuǎn xué lí xiào zhèng míng， zài qù běn dì chū rù jìng bàn lǐ jū liú qiān chū bèi àn。','Trước tiên em xin giấy chứng nhận chuyển trường thôi học, sau đó đến cơ quan xuất nhập cảnh địa phương làm thủ tục đăng ký chuyển đi cư trú.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_03','V525','阮明',3,'迁出备案完成，原有居留许可还能继续使用一段时间吗？','qiān chū bèi àn wán chéng， yuán yǒu jū liú xǔ kě hái néng jì xù shǐ yòng yī duàn shí jiān ma？','Sau khi hoàn tất đăng ký chuyển đi, giấy phép cư trú cũ có còn dùng được một thời gian nữa không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_04','V525','老师',4,'迁出当日原居留自动失效，抵达新城市必须三十日内重新办居留嘛。','qiān chū dāng rì yuán jū liú zì dòng shī xiào， dǐ dá xīn chéng shì bì xū sān shí rì nèi chóng xīn bàn jū liú ma。','Ngay ngày làm thủ tục chuyển đi, giấy cư trú cũ tự động hết hiệu lực, đến thành phố mới phải làm lại cư trú trong vòng ba mươi ngày đấy.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_05','V525','阮明',5,'转学途中跨城市出行，没有有效居留可以凭转学证明通行？','zhuǎn xué tú zhōng kuà chéng shì chū xíng， méi yǒu yǒu xiào jū liú kě yǐ píng zhuǎn xué zhèng míng tōng xíng？','Trong lúc di chuyển liên tỉnh để chuyển trường, không có giấy cư trú hợp lệ thì có thể dùng giấy chứng nhận chuyển trường để đi lại không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_06','V525','老师',6,'迁出时出入境会开具三十天过渡临时停留证明用于中转。','qiān chū shí chū rù jìng huì kāi jù sān shí tiān guò dù lín shí tíng liú zhèng míng yòng yú zhōng zhuǎn。','Khi làm thủ tục chuyển đi, cơ quan xuất nhập cảnh sẽ cấp giấy tạm trú quá độ ba mươi ngày để dùng cho việc trung chuyển.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_07','V525','阮明',7,'新学校接收后，全套居留材料要重新提交一遍？','xīn xué xiào jiē shōu hòu， quán tào jū liú cái liào yào chóng xīn tí jiāo yī biàn？','Sau khi trường mới tiếp nhận, toàn bộ hồ sơ cư trú có phải nộp lại từ đầu không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_08','V525','老师',8,'全部材料重新递交，按新生标准办理当地居留许可。','quán bù cái liào chóng xīn dì jiāo， àn xīn shēng biāo zhǔn bàn lǐ dāng dì jū liú xǔ kě。','Toàn bộ hồ sơ phải nộp lại, làm thủ tục cư trú tại địa phương theo tiêu chuẩn sinh viên mới.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_09','V525','阮明',9,'我先办好离校转学证明，再去大厅做迁出备案。','wǒ xiān bàn hǎo lí xiào zhuǎn xué zhèng míng， zài qù dà tīng zuò qiān chū bèi àn。','Em sẽ làm giấy chứng nhận thôi học chuyển trường trước, rồi đến quầy làm thủ tục đăng ký chuyển đi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT526','SV4','更换校外租房地址，10日内办理居留地址变更',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V526','SIT526','P1','that_bai_nhe','tuy_y',NULL,'外籍人员更换居住地址法定十日内向社区更新住宿信息，多次逾期备案会影响后续居留续签审核。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_01','V526','阮明',1,'网格员，我刚换出租房，超过十天没办住宿变更登记。','wǎng gé yuán， wǒ gāng huàn chū zū fáng， chāo guò shí tiān méi bàn zhù sù biàn gēng dēng jì。','Anh/chị tổ dân phố ơi, em vừa chuyển chỗ trọ, quá mười ngày rồi mà chưa đăng ký thay đổi chỗ ở.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_02','V526','网格员',2,'外籍人员换居住地址必须十日之内备案，逾期会有警告记录。','wài jí rén yuán huàn jū zhù dì zhǐ bì xū shí rì zhī nèi bèi àn， yú qī huì yǒu jǐng gào jì lù。','Người nước ngoài khi đổi chỗ ở phải đăng ký trong vòng mười ngày, để quá hạn là bị ghi cảnh cáo đó nha.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_03','V526','阮明',3,'我搬家后忙着上课完全忘记，现在补办还会罚款吗？','wǒ bān jiā hòu máng zhe shàng kè wán quán wàng jì， xiàn zài bǔ bàn hái huì fá kuǎn ma？','Em chuyển nhà xong bận đi học nên quên mất luôn, giờ bổ sung thì có bị phạt tiền không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_04','V526','网格员',4,'首次轻微超期仅书面警告，多次超期才会产生行政处罚嘛。','shǒu cì qīng wēi chāo qī jǐn shū miàn jǐng gào， duō cì chāo qī cái huì chǎn shēng xíng zhèng chǔ fá ma。','Lần đầu trễ hạn nhẹ thì chỉ cảnh cáo bằng văn bản thôi, để trễ nhiều lần mới bị xử phạt hành chính chứ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_05','V526','阮明',5,'补办地址变更需要房东带房产证一起来社区备案吗？','bǔ bàn dì zhǐ biàn gēng xū yào fáng dōng dài fáng chǎn zhèng yì qǐ lái shè qū bèi àn ma？','Để bổ sung đổi địa chỉ thì có cần chủ nhà mang giấy chứng nhận nhà đất đến khu phố cùng đăng ký không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_06','V526','网格员',6,'需要房东到场签字备案，同步打印新住宿登记单。','xū yào fáng dōng dào chǎng qiān zì bèi àn， tóng bù dǎ yìn xīn zhù sù dēng jì dān。','Cần chủ nhà có mặt ký tên đăng ký, đồng thời in luôn phiếu đăng ký tạm trú mới.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_07','V526','阮明',7,'我现在联系房东过来社区，立刻补办地址变更登记。','wǒ xiàn zài lián xì fáng dōng guò lái shè qū， lì kè bǔ bàn dì zhǐ biàn gēng dēng jì。','Vậy giờ em liên hệ chủ nhà qua khu phố, làm bổ sung đăng ký đổi địa chỉ ngay.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT527','SV4','护照个人信息更新，同步更新居留证件信息',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V527','SIT527','P1','suon_se','chinh_thuc',NULL,'护照姓名、国籍、证件编号等核心信息变动后，必须同步更新居留许可，证件信息不一致会被判定无效证件。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_01','V527','阮明',1,'您好，我的新护照姓名拼写更新，同步变更居留卡信息。','nín hǎo， wǒ de xīn hù zhào xìng míng pīn xiě gēng xīn， tóng bù biàn gēng jū liú kǎ xìn xī。','Xin chào, hộ chiếu mới của tôi đã cập nhật cách viết tên, tôi muốn đồng bộ thay đổi thông tin trên thẻ cư trú.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_02','V527','工作人员',2,'递交新护照、使馆出具的信息变更说明文件、证件照片。','dì jiāo xīn hù zhào、 shǐ guǎn chū jù de xìn xī biàn gēng shuō míng wén jiàn、 zhèng jiàn zhào piān。','Anh/chị nộp hộ chiếu mới, văn bản xác nhận thay đổi thông tin do đại sứ quán cấp, và ảnh thẻ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_03','V527','阮明',3,'居留卡信息变更完成，有效期延续原来的到期时间？','jū liú kǎ xìn xī biàn gēng wán chéng， yǒu xiào qī yán xù yuán lái de dào qī shí jiān？','Sau khi thay đổi thông tin thẻ cư trú xong, thời hạn hiệu lực vẫn giữ nguyên như ngày hết hạn cũ chứ ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_04','V527','工作人员',4,'有效期不变，仅更新证件上的姓名、护照编号信息。','yǒu xiào qī bù biàn， jǐn gēng xīn zhèng jiàn shàng de xìng míng、 hù zhào biān hào xìn xī。','Thời hạn không đổi, chỉ cập nhật lại tên và số hộ chiếu trên giấy tờ thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_05','V527','阮明',5,'变更完成后出入境、高铁酒店查验不会出现信息不符？','biàn gēng wán chéng hòu chū rù jìng、 gāo tiě jiǔ diàn chá yàn bú huì chū xiàn xìn xī bù fú？','Sau khi thay đổi xong, khi kiểm tra ở xuất nhập cảnh, tàu cao tốc hay khách sạn sẽ không bị lệch thông tin chứ ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_06','V527','工作人员',6,'系统实时同步更新，全国查验终端同步刷新信息。','xì tǒng shí shí tóng bù gēng xīn， quán guó chá yàn zhōng duān tóng bù shuā xīn xìn xī。','Hệ thống cập nhật đồng bộ theo thời gian thực, tất cả các đầu kiểm tra trên toàn quốc đều được làm mới thông tin cùng lúc.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_07','V527','阮明',7,'全套材料整理完毕，麻烦受理信息变更业务。','quán tào cái liào zhěng lǐ wán bì， má fán shòu lǐ xìn xī biàn gēng yè wù。','Toàn bộ hồ sơ tôi đã chuẩn bị xong, phiền anh/chị tiếp nhận xử lý thay đổi thông tin giúp tôi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT528','SV5','咨询留学生合法校外实习签证备案流程',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V528','SIT528','P1','twist','ban_chinh_thuc',NULL,'外籍留学生无备案校外实习属于非法务工，一旦查实会行政处罚，严重者不予续签居留许可。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_01','V528','阮明',1,'老师，我想找校外企业实习，咨询留学生务工备案流程。','lǎo shī， wǒ xiǎng zhǎo xiào wài qǐ yè shí xí， zī xún liú xué shēng wù gōng bèi àn liú chéng。','Thưa thầy/cô, em muốn tìm doanh nghiệp bên ngoài để thực tập, muốn hỏi về thủ tục đăng ký làm việc cho du học sinh ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_02','V528','老师',2,'校外实习必须企业、学校、学生三方签订实习协议备案。','xiào wài shí xí bì xū qǐ yè、 xué xiào、 xué shēng sān fāng qiān dìng shí xí xié yì bèi àn。','Thực tập bên ngoài trường bắt buộc doanh nghiệp, nhà trường và sinh viên ba bên ký thỏa thuận thực tập rồi đăng ký.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_03','V528','阮明',3,'不提前备案直接去实习，会不会影响我的居留续签呢？','bù tí qián bèi àn zhí jiē qù shí xí， huì bú huì yǐng xiǎng wǒ de jū liú xù qiān ne？','Nếu không đăng ký trước mà cứ đi thực tập luôn thì có ảnh hưởng đến việc gia hạn cư trú của em không ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_04','V528','老师',4,'无备案校外务工属于非法就业，查到会罚款并缩短居留期限嘛。','wú bèi àn xiào wài wù gōng shǔ yú fēi fǎ jiù yè， chá dào huì fá kuǎn bìng suō duǎn jū liú qī xiàn ma。','Làm việc bên ngoài mà không đăng ký thì coi là làm việc bất hợp pháp, bị phát hiện là vừa bị phạt tiền vừa bị rút ngắn thời hạn cư trú đấy.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_05','V528','阮明',5,'实习备案每个学期只能办理一次，中途更换企业能重新备案吗？','shí xí bèi àn měi gè xué qī zhǐ néng bàn lǐ yī cì， zhōng tú gēng huàn qǐ yè néng chóng xīn bèi àn ma？','Đăng ký thực tập mỗi học kỳ chỉ được làm một lần, giữa chừng đổi doanh nghiệp thì có đăng ký lại được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_06','V528','老师',6,'中途更换实习单位需要注销原有备案，重新提交三方协议。','zhōng tú gēng huàn shí xí dān wèi xū yào zhù xiāo yuán yǒu bèi àn， chóng xīn tí jiāo sān fāng xié yì。','Giữa chừng đổi nơi thực tập thì cần hủy đăng ký cũ, rồi nộp lại thỏa thuận ba bên mới.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_07','V528','阮明',7,'办理备案需要企业提供营业执照复印件加盖公章吧？','bàn lǐ bèi àn xū yào qǐ yè tí gōng yíng yè zhí zhào fù yìn jiàn jiā gài gōng zhāng ba？','Để đăng ký thì cần doanh nghiệp cung cấp bản sao giấy phép kinh doanh có đóng dấu đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_08','V528','老师',8,'没错，企业资质文件是实习备案必备核心材料。','méi cuò， qǐ yè zī zhì wén jiàn shì shí xí bèi àn bì bèi hé xīn cái liào。','Đúng vậy, giấy tờ chứng nhận tư cách doanh nghiệp là hồ sơ cốt lõi bắt buộc phải có khi đăng ký thực tập.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_09','V528','阮明',9,'我先和实习企业沟通准备资质材料，再来办理备案。','wǒ xiān hé shí xí qǐ yè gōu tōng zhǔn bèi zī zhì cái liào， zài lái bàn lǐ bèi àn。','Em sẽ trao đổi với doanh nghiệp thực tập để chuẩn bị giấy tờ trước, rồi quay lại làm thủ tục đăng ký.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT529','SV5','办理留学生校内勤工助学务工备案证明',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V529','SIT529','P1','suon_se','tuy_y',NULL,'留学生校内勤工助学同样有严格时长限制，校内备案仅学院留存，校外实习必须同步向出入境备案。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_01','V529','阮明',1,'老师，我申请校内图书馆助教兼职，需要办务工备案吗？','lǎo shī， wǒ shēn qǐng xiào nèi tú shū guǎn zhù jiào jiān zhí， xū yào bàn wù gōng bèi àn ma？','Thầy/cô ơi, em xin làm trợ giảng bán thời gian ở thư viện trong trường, vậy có cần đăng ký làm việc không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_02','V529','老师',2,'校内勤工助学也需要开具勤工助学备案单留存系统哦。','xiào nèi qín gōng zhù xué yě xū yào kāi jù qín gōng zhù xué bèi àn dān liú cún xì tǒng ó。','Làm thêm trong trường cũng cần lập phiếu đăng ký lao động vừa học vừa làm để lưu vào hệ thống đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_03','V529','阮明',3,'校内兼职每周务工时长上限还是二十小时对吧？','xiào nèi jiān zhí měi zhōu wù gōng shí cháng shàng xiàn hái shì èr shí xiǎo shí duì ba？','Làm thêm trong trường thì giới hạn giờ làm mỗi tuần vẫn là hai mươi tiếng đúng không thầy/cô?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_04','V529','老师',4,'学期内每周不超二十小时，寒暑假放宽至四十小时。','xué qī nèi měi zhōu bù chāo èr shí xiǎo shí， hán shǔ jià fàng kuān zhì sì shí xiǎo shí。','Trong học kỳ thì không quá hai mươi tiếng mỗi tuần, nghỉ hè đông thì được nới lên bốn mươi tiếng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_05','V529','阮明',5,'这份备案单需要带去出入境更新居留证件信息？','zhè fèn bèi àn dān xū yào dài qù chū rù jìng gēng xīn jū liú zhèng jiàn xìn xī？','Phiếu đăng ký này có cần mang đến xuất nhập cảnh để cập nhật thông tin thẻ cư trú không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_06','V529','老师',6,'校内兼职无需去出入境，仅学院内部系统备案存档。','xiào nèi jiān zhí wú xū qù chū rù jìng， jǐn xué yuàn nèi bù xì tǒng bèi àn cún dàng。','Làm thêm trong trường thì không cần ra xuất nhập cảnh, chỉ cần đăng ký lưu trữ trong hệ thống nội bộ của khoa thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_07','V529','阮明',7,'那我填好勤工助学申请表，麻烦老师盖章备案。','nà wǒ tián hǎo qín gōng zhù xué shēn qǐng biǎo， má fán lǎo shī gài zhāng bèi àn。','Vậy em điền xong đơn đăng ký vừa học vừa làm, phiền thầy/cô đóng dấu xác nhận giúp em.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT530','SV5','咨询逾期打工、超时务工对签证续签的影响',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V530','SIT530','P1','twist','chinh_thuc',NULL,'中国法律严格限制外籍留学生务工时长与务工范围，非法就业会直接影响居留续签，甚至限期离境。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_01','V530','阮明',1,'警官，如果留学生超时打工或者无备案务工，续签居留会怎样？','jǐng guān， rú guǒ liú xué shēng chāo shí dǎ gōng huò zhě wú bèi àn wù gōng， xù qiān jū liú huì zěn yàng？','Thưa cán bộ, nếu du học sinh làm thêm quá giờ hoặc làm việc không đăng ký thì việc gia hạn cư trú sẽ ra sao ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_02','V530','辅警',2,'首次查实非法务工罚款，居留许可缩短有效期半年呢。','shǒu cì chá shí fēi fǎ wù gōng fá kuǎn， jū liú xǔ kě suō duǎn yǒu xiào qī bàn nián ne。','Lần đầu bị phát hiện làm việc trái phép thì bị phạt tiền, giấy phép cư trú bị rút ngắn hiệu lực nửa năm đấy.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_03','V530','阮明',3,'多次违规超时务工，会直接拒绝续签学生居留吗？','duō cì wéi guī chāo shí wù gōng， huì zhí jiē jù jué xù qiān xué shēng jū liú ma？','Nếu vi phạm làm quá giờ nhiều lần thì có bị từ chối thẳng việc gia hạn cư trú sinh viên không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_04','V530','辅警',4,'两次及以上非法务工记录，出入境直接驳回续签申请嘛。','liǎng cì jí yǐ shàng fēi fǎ wù gōng jì lù， chū rù jìng zhí jiē bó huí xù qiān shēn qǐng ma。','Có từ hai lần vi phạm làm việc trái phép trở lên thì xuất nhập cảnh sẽ bác đơn gia hạn luôn.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_05','V530','阮明',5,'寒暑假四十小时上限，如果超过时长也算违规务工？','hán shǔ jià sì shí xiǎo shí shàng xiàn， rú guǒ chāo guò shí cháng yě suàn wéi guī wù gōng？','Giới hạn bốn mươi tiếng dịp nghỉ hè đông, nếu vượt quá thời gian đó thì cũng tính là làm việc vi phạm phải không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_06','V530','辅警',6,'无论学期还是假期，超出规定时长均判定非法就业。','wú lùn xué qī hái shì jià qī， chāo chū guī dìng shí cháng jūn pàn dìng fēi fǎ jiù yè。','Dù là trong học kỳ hay kỳ nghỉ, hễ vượt quá thời gian quy định đều bị coi là việc làm bất hợp pháp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_07','V530','阮明',7,'合法备案实习，更换单位忘记注销旧备案会有记录吗？','hé fǎ bèi àn shí xí， gēng huàn dān wèi wàng jì zhù xiāo jiù bèi àn huì yǒu jì lù ma？','Thực tập đã đăng ký hợp pháp, nếu đổi nơi làm mà quên hủy đăng ký cũ thì có bị ghi nhận vi phạm không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_08','V530','辅警',8,'旧备案未注销会判定多单位同时务工，同样违规。','jiù bèi àn wèi zhù xiāo huì pàn dìng duō dān wèi tóng shí wù gōng， tóng yàng wéi guī。','Đăng ký cũ chưa hủy sẽ bị coi là làm việc cùng lúc ở nhiều nơi, cũng là vi phạm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_09','V530','阮明',9,'我会严格遵守务工时长规定，提前办好全部实习备案。','wǒ huì yán gé zūn shǒu wù gōng shí cháng guī dìng， tí qián bàn hǎo quán bù shí xí bèi àn。','Em sẽ tuân thủ nghiêm quy định về thời gian làm việc, làm đầy đủ đăng ký thực tập trước.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT531','SV6','毕业申请短期停留签证（毕业生留华缓冲期）',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V531','SIT531','P1','suon_se','ban_chinh_thuc',NULL,'留学生毕业后可申请最长180天短期停留缓冲签证，该签证禁止任何形式务工、实习，到期必须离境。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_01','V531','阮明',1,'您好，我顺利完成学业毕业，申请毕业生短期停留签证。','nín hǎo， wǒ shùn lì wán chéng xué yè bì yè， shēn qǐng bì yè shēng duǎn qī tíng liú qiān zhèng。','Xin chào, tôi đã hoàn thành tốt việc học và tốt nghiệp, muốn xin visa lưu trú ngắn hạn dành cho sinh viên tốt nghiệp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_02','V531','工作人员',2,'递交毕业证、毕业离校证明、住宿登记单、证件照片。','dì jiāo bì yè zhèng、 bì yè lí xiào zhèng míng、 zhù sù dēng jì dān、 zhèng jiàn zhào piān。','Anh/chị nộp bằng tốt nghiệp, giấy chứng nhận thôi học sau tốt nghiệp, phiếu đăng ký tạm trú và ảnh thẻ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_03','V531','阮明',3,'短期停留签证最长能办理多久，是三十天还是九十天？','duǎn qī tíng liú qiān zhèng zuì zhǎng néng bàn lǐ duō jiǔ， shì sān shí tiān hái shì jiǔ shí tiān？','Visa lưu trú ngắn hạn này tối đa được bao lâu, là ba mươi ngày hay chín mươi ngày ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_04','V531','工作人员',4,'毕业生缓冲居留最长一百八十天，可自由选择时长。','bì yè shēng huǎn chōng jū liú zuì zhǎng yì bǎi bā shí tiān， kě zì yóu xuǎn zé shí cháng。','Thời gian cư trú đệm cho sinh viên tốt nghiệp tối đa là một trăm tám mươi ngày, anh/chị có thể tự chọn thời hạn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_05','V531','阮明',5,'这段短期居留期间，能不能正常办理校外实习备案？','zhè duàn duǎn qī jū liú qī jiān， néng bù néng zhèng cháng bàn lǐ xiào wài shí xí bèi àn？','Trong thời gian lưu trú ngắn hạn này, tôi có thể làm thủ tục đăng ký thực tập bên ngoài trường bình thường không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_06','V531','工作人员',6,'毕业短期停留签证禁止务工、实习，仅用于旅游采购。','bì yè duǎn qī tíng liú qiān zhèng jìn zhǐ wù gōng、 shí xí， jǐn yòng yú lǚ yóu cǎi gòu。','Visa lưu trú ngắn hạn sau tốt nghiệp cấm làm việc, thực tập, chỉ dùng để du lịch, mua sắm thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_07','V531','阮明',7,'缓冲期到期必须离境，无法再次延期对吗？','huǎn chōng qī dào qī bì xū lí jìng， wú fǎ zài cì yán qī duì ma？','Hết thời gian đệm là phải xuất cảnh, không thể gia hạn thêm lần nữa đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_08','V531','工作人员',8,'无特殊重大事由，毕业短期签证不予二次延期。','wú tè shū zhòng dà shì yóu， bì yè duǎn qī qiān zhèng bù yǔ èr cì yán qī。','Nếu không có lý do đặc biệt quan trọng thì visa ngắn hạn sau tốt nghiệp sẽ không được gia hạn lần hai.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_09','V531','阮明',9,'全部材料备齐，麻烦受理短期停留签证申请。','quán bù cái liào bèi qí， má fán shòu lǐ duǎn qī tíng liú qiān zhèng shēn qǐng。','Hồ sơ tôi đã chuẩn bị đầy đủ, phiền anh/chị tiếp nhận xử lý đơn xin visa lưu trú ngắn hạn giúp tôi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT532','SV6','办理留学回国人员证明，用于境外学历认证',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V532','SIT532','P1','twist','ban_chinh_thuc',NULL,'留学回国人员证明是境外学历认证必备材料，需要完整留存全部在华居留、出入境记录，证件丢失需打印官方流水补充。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_01','V532','阮明',1,'老师，我毕业要办留学回国证明，用来回国做学历认证。','lǎo shī， wǒ bì yè yào bàn liú xué huí guó zhèng míng， yòng lái huí guó zuò xué lì rèn zhèng。','Thưa thầy/cô, em sắp tốt nghiệp cần làm giấy chứng nhận du học sinh về nước, để dùng công nhận bằng cấp ở quê nhà.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_02','V532','老师',2,'需要提交护照全套签证页复印件、毕业证、毕业离校回执。','xū yào tí jiāo hù zhào quán tào qiān zhèng yè fù yìn jiàn、 bì yè zhèng、 bì yè lí xiào huí zhí。','Cần nộp bản sao toàn bộ các trang visa trong hộ chiếu, bằng tốt nghiệp, và biên nhận thôi học sau tốt nghiệp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_03','V532','阮明',3,'我的旧护照剪角丢失，只有新护照复印件可以提交吗？','wǒ de jiù hù zhào jiǎn jiǎo diū shī， zhǐ yǒu xīn hù zhào fù yìn jiàn kě yǐ tí jiāo ma？','Hộ chiếu cũ của em bị cắt góc và thất lạc rồi, chỉ còn bản sao hộ chiếu mới thì có nộp được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_04','V532','老师',4,'缺少完整在华居留记录页面，暂时无法开具回国证明嘛。','quē shǎo wán zhěng zài huá jū liú jì lù yè miàn， zàn shí wú fǎ kāi jù huí guó zhèng míng ma。','Thiếu trang ghi đầy đủ lịch sử cư trú tại Trung Quốc thì tạm thời chưa thể cấp giấy chứng nhận về nước được đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_05','V532','阮明',5,'派出所能打印出入境全部入境出境记录替代旧护照复印件吗？','pài chū suǒ néng dǎ yìn chū rù jìng quán bù rù jìng chū jìng jì lù tì dài jiù hù zhào fù yìn jiàn ma？','Vậy công an có thể in toàn bộ hồ sơ xuất nhập cảnh để thay thế bản sao hộ chiếu cũ không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_06','V532','老师',6,'可以，去出入境大厅打印完整出入境流水作为补充材料。','kě yǐ， qù chū rù jìng dà tīng dǎ yìn wán zhěng chū rù jìng liú shuǐ zuò wéi bǔ chōng cái liào。','Được, em ra quầy xuất nhập cảnh in đầy đủ lịch sử xuất nhập cảnh làm hồ sơ bổ sung là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_07','V532','阮明',7,'我先去打印出入境记录，补齐材料再来申请回国证明。','wǒ xiān qù dǎ yìn chū rù jìng jì lù， bǔ qí cái liào zài lái shēn qǐng huí guó zhèng míng。','Vậy em đi in hồ sơ xuất nhập cảnh trước, bổ sung đầy đủ giấy tờ rồi quay lại xin giấy chứng nhận về nước.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT533','SV6','退学终止学业，注销有效居留许可限期离境',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V533','SIT533','P1','that_bai_nhe','chinh_thuc',NULL,'退学学籍终止，学生居留许可注销，缓冲期仅用于收拾行李离境，缓冲到期无合法续签渠道，超期属于非法滞留。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_01','V533','阮明',1,'警官，我办理退学手续，前来注销现有的学生居留许可。','jǐng guān， wǒ bàn lǐ tuì xué shǒu xù， qián lái zhù xiāo xiàn yǒu de xué shēng jū liú xǔ kě。','Chào cán bộ, tôi làm thủ tục thôi học, đến để hủy giấy phép cư trú diện học sinh hiện có.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_02','V533','民警',2,'递交退学离校证明，系统注销居留后给予三十天合法停留缓冲期。','dì jiāo tuì xué lí xiào zhèng míng， xì tǒng zhù xiāo jū liú hòu jǐ yǔ sān shí tiān hé fǎ tíng liú huǎn chōng qī。','Nộp giấy xác nhận thôi học, hệ thống sẽ hủy cư trú và cho anh thời gian đệm hợp pháp ba mươi ngày để lưu lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_03','V533','阮明',3,'三十天缓冲期内可以外出旅游，不受出行限制吗？','sān shí tiān huǎn chōng qī nèi kě yǐ wài chū lǚ yóu， bù shòu chū xíng xiàn zhì ma？','Trong ba mươi ngày đệm đó tôi có thể đi du lịch, không bị hạn chế đi lại đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_04','V533','民警',4,'出行不受限，但缓冲到期必须离境，不能申请续签延期。','chū xíng bù shòu xiàn， dàn huǎn chōng dào qī bì xū lí jìng， bù néng shēn qǐng xù qiān yán qī。','Đi lại không bị hạn chế, nhưng hết thời gian đệm là bắt buộc phải xuất cảnh, không thể xin gia hạn thêm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_05','V533','阮明',5,'如果三十天内没有买到回国机票，超期停留会如何处罚？','rú guǒ sān shí tiān nèi méi yǒu mǎi dào huí guó jī piào， chāo qī tíng liú huì rú hé chǔ fá？','Nếu trong ba mươi ngày mà tôi không mua được vé máy bay về nước thì việc ở quá hạn sẽ bị xử phạt thế nào ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_06','V533','民警',6,'退学后无有效学籍，超期一日产生对应罚款，还留下不良入境记录。','tuì xué hòu wú yǒu xiào xué jí， chāo qī yī rì chǎn shēng duì yìng fá kuǎn， hái liú xià bù liáng rù jìng jì lù。','Sau khi thôi học thì không còn tư cách học sinh hợp lệ, ở quá hạn một ngày là bị phạt tương ứng, còn để lại hồ sơ nhập cảnh không tốt.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_07','V533','阮明',7,'缓冲期内只能单次出境，中途回国后无法再次入境中国？','huǎn chōng qī nèi zhǐ néng dān cì chū jìng， zhōng tú huí guó hòu wú fǎ zài cì rù jìng zhōng guó？','Trong thời gian đệm chỉ được xuất cảnh một lần, nếu giữa chừng về nước rồi thì không thể nhập cảnh Trung Quốc lại nữa phải không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_08','V533','民警',8,'居留注销后签证同步失效，离境后不能再次入境。','jū liú zhù xiāo hòu qiān zhèng tóng bù shī xiào， lí jìng hòu bù néng zài cì rù jìng。','Sau khi hủy cư trú thì visa cũng mất hiệu lực theo, xuất cảnh rồi là không thể nhập cảnh lại được nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_09','V533','阮明',9,'我会在三十天缓冲期内订购机票按时返回越南。','wǒ huì zài sān shí tiān huǎn chōng qī nèi dìng gòu jī piào àn shí fǎn huí yuè nán。','Tôi sẽ đặt vé máy bay trong ba mươi ngày đệm để về Việt Nam đúng hạn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT534','SV6','签证到期前彻底回国，咨询居留注销流程',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V534','SIT534','P1','suon_se','tuy_y',NULL,'留学生永久离境建议主动注销居留许可，证件到期自动失效虽无罚款，但会提升下次来华签证的审核严格程度。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_01','V534','阮明',1,'警官，我毕业直接回国不再来华，需要注销居留许可吗？','jǐng guān， wǒ bì yè zhí jiē huí guó bù zài lái huá， xū yào zhù xiāo jū liú xǔ kě ma？','Cán bộ ơi, tôi tốt nghiệp về nước luôn không quay lại Trung Quốc nữa thì có cần hủy giấy phép cư trú không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_02','V534','辅警',2,'长期离境建议提前注销居留，避免休眠证件产生异常记录哈。','cháng qī lí jìng jiàn yì tí qián zhù xiāo jū liú， bì miǎn xiū mián zhèng jiàn chǎn shēng yì cháng jì lù hā。','Nếu đi lâu dài thì nên chủ động hủy cư trú trước, tránh để giấy tờ ở trạng thái treo phát sinh hồ sơ bất thường đó nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_03','V534','阮明',3,'不主动注销，居留到期自动失效会不会留下负面记录？','bù zhǔ dòng zhù xiāo， jū liú dào qī zì dòng shī xiào huì bú huì liú xià fù miàn jì lù？','Nếu không chủ động hủy mà để cư trú tự hết hạn thì có bị ghi hồ sơ xấu không nhỉ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_04','V534','辅警',4,'到期自动失效无处罚，但下次申请来华签证会增加审核难度。','dào qī zì dòng shī xiào wú chǔ fá， dàn xià cì shēn qǐng lái huá qiān zhèng huì zēng jiā shěn hé nán dù。','Tự hết hạn thì không bị phạt gì, nhưng lần sau xin visa sang lại sẽ bị xét duyệt khó hơn đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_05','V534','阮明',5,'注销居留只需要带护照，不用额外准备其他证明？','zhù xiāo jū liú zhǐ xū yào dài hù zhào， bù yòng é wài zhǔn bèi qí tā zhèng míng？','Hủy cư trú chỉ cần mang hộ chiếu thôi, không cần chuẩn bị thêm giấy tờ gì khác đúng không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_06','V534','辅警',6,'携带毕业证、护照现场办理注销，当场打印注销回执。','xié dài bì yè zhèng、 hù zhào xiàn chǎng bàn lǐ zhù xiāo， dāng chǎng dǎ yìn zhù xiāo huí zhí。','Mang theo bằng tốt nghiệp với hộ chiếu đến làm trực tiếp là được, làm xong là in luôn biên nhận hủy tại chỗ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_07','V534','阮明',7,'回国之后如果再来留学，凭注销回执办理新签证更顺畅？','huí guó zhī hòu rú guǒ zài lái liú xué， píng zhù xiāo huí zhí bàn lǐ xīn qiān zhèng gèng shùn chàng？','Sau này về nước rồi mà quay lại du học tiếp, cầm biên nhận hủy này xin visa mới sẽ suôn sẻ hơn phải không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_08','V534','辅警',8,'是的，完整注销记录有利于后续签证审核。','shì de， wán zhěng zhù xiāo jì lù yǒu lì yú hòu xù qiān zhèng shěn hé。','Đúng vậy, hồ sơ hủy đầy đủ sẽ giúp việc xét duyệt visa sau này thuận lợi hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_09','V534','阮明',9,'那我离校前提前来大厅办理居留注销手续。','nà wǒ lí xiào qián tí qián lái dà tīng bàn lǐ jū liú zhù xiāo shǒu xù。','Vậy trước khi rời trường tôi sẽ đến sảnh làm thủ tục hủy cư trú sớm.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT535','SV6','毕业短期签证到期无法按时离境，申请延期缓冲',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V535','SIT535','P1','twist','chinh_thuc',NULL,'毕业生短期缓冲签证一般不可延期，仅航班取消、重病住院等不可抗力可短期延长停留期限，且需缴纳签证工本费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_01','V535','阮明',1,'您好，我的毕业短期停留签证即将到期，机票延误无法按时离境。','nín hǎo， wǒ de bì yè duǎn qī tíng liú qiān zhèng jí jiāng dào qī， jī piào yán wù wú fǎ àn shí lí jìng。','Xin chào, visa lưu trú ngắn hạn sau tốt nghiệp của tôi sắp hết hạn, nhưng máy bay bị hoãn nên không thể xuất cảnh đúng hạn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_02','V535','工作人员',2,'毕业短期签证原则上不予延期，仅突发客观事由可特殊审批。','bì yè duǎn qī qiān zhèng yuán zé shàng bù yǔ yán qī， jǐn tū fā kè guān shì yóu kě tè shū shěn pī。','Về nguyên tắc visa ngắn hạn sau tốt nghiệp không được gia hạn, chỉ trường hợp bất khả kháng khách quan mới được xét duyệt đặc biệt.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_03','V535','阮明',3,'国际航班大面积取消，航空公司开具了延误证明作为凭证。','guó jì háng bān dà miàn jī qǔ xiāo， háng kōng gōng sī kāi jù le yán wù zhèng míng zuò wéi píng zhèng。','Chuyến bay quốc tế bị hủy hàng loạt, hãng hàng không đã cấp giấy xác nhận hoãn chuyến làm bằng chứng rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_04','V535','工作人员',4,'航班延误属于客观特殊情况，最多给予十五天短期延期嘛。','háng bān yán wù shǔ yú kè guān tè shū qíng kuàng， zuì duō jǐ yǔ shí wǔ tiān duǎn qī yán qī ma。','Hoãn chuyến bay thuộc trường hợp khách quan đặc biệt, tối đa được gia hạn ngắn hạn mười lăm ngày thôi nhé.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_05','V535','阮明',5,'十五天延期需要额外收取签证手续费，还是免费办理？','shí wǔ tiān yán qī xū yào é wài shōu qǔ qiān zhèng shǒu xù fèi， hái shì miǎn fèi bàn lǐ？','Gia hạn mười lăm ngày này có phải đóng thêm phí thủ tục visa không, hay là làm miễn phí ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_06','V535','工作人员',6,'短期延期统一收取标准签证工本费，无法免除费用。','duǎn qī yán qī tǒng yī shōu qǔ biāo zhǔn qiān zhèng gōng běn fèi， wú fǎ miǎn chú fèi yòng。','Gia hạn ngắn hạn vẫn thu phí làm chứng visa theo mức chung, không được miễn phí.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_07','V535','阮明',7,'递交航空公司延误证明、护照、白底照片即可受理对吗？','dì jiāo háng kōng gōng sī yán wù zhèng míng、 hù zhào、 bái dǐ zhào piān jí kě shòu lǐ duì ma？','Tôi nộp giấy xác nhận hoãn chuyến của hãng bay, hộ chiếu, ảnh nền trắng là được xử lý đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_08','V535','工作人员',8,'全部材料齐全，三个工作日完成延期审批制证。','quán bù cái liào qí quán， sān gè gōng zuò rì wán chéng yán qī shěn pī zhì zhèng。','Đầy đủ giấy tờ thì trong ba ngày làm việc sẽ hoàn tất xét duyệt gia hạn và làm chứng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_09','V535','阮明',9,'我携带航班延误证明，现在递交延期申请材料。','wǒ xié dài háng bān yán wù zhèng míng， xiàn zài dì jiāo yán qī shēn qǐng cái liào。','Tôi mang theo giấy xác nhận hoãn chuyến bay, giờ xin nộp hồ sơ xin gia hạn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT601','SF1','下载注册国际通用视频软件，和父母跨国视频通话',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V601','SIT601','P1','suon_se','tuy_y',NULL,'国内本土社交软件海外受限，留学生普遍使用国际通用通讯软件和境外家人联络。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_01','V601','阮明',1,'小林，我想装一款国外能用的视频软件跟爸妈通话，你知道哪款好用吗？','xiǎo lín， wǒ xiǎng zhuāng yī kuǎn guó wài néng yòng de shì pín ruǎn jiàn gēn bà mā tōng huà， nǐ zhī dào nǎ kuǎn hǎo yòng ma？','Tiểu Lâm ơi, tớ muốn cài một phần mềm video mà nước ngoài dùng được để gọi cho bố mẹ, cậu biết cái nào ngon không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_02','V601','小林',2,'这款APP国内外都能互通，下载之后用邮箱注册就行啦。','zhè kuǎn APP guó nèi wài dōu néng hù tōng， xià zài zhī hòu yòng yóu xiāng zhù cè jiù xíng la。','App này trong nước với nước ngoài đều liên lạc được, tải xong rồi đăng ký bằng email là xong ngay ấy mà.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_03','V601','阮明',3,'国内手机号注册的话，越南那边收得到验证码吗？','guó nèi shǒu jī hào zhù cè de huà， yuè nán nà biān shōu dé dào yàn zhèng mǎ ma？','Nếu đăng ký bằng số điện thoại trong nước thì bên Việt Nam có nhận được mã xác nhận không nhỉ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_04','V601','小林',4,'手机号跨国有延迟，直接绑定邮箱登录最稳妥呢。','shǒu jī hào kuà guó yǒu yán chí， zhí jiē bǎng dìng yóu xiāng dēng lù zuì wěn tuǒ ne。','Số điện thoại xuyên quốc gia hay bị trễ lắm, cứ gắn email vào đăng nhập là chắc ăn nhất đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_05','V601','阮明',5,'注册完成后，直接搜索爸妈的账号就能发起视频吗？','zhù cè wán chéng hòu， zhí jiē sōu suǒ bà mā de zhàng hào jiù néng fā qǐ shì pín ma？','Đăng ký xong là cứ tìm tài khoản của bố mẹ rồi gọi video luôn được hả?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_06','V601','小林',6,'没错，还能发照片、短视频，日常报平安很方便。','méi cuò， hái néng fā zhào piān、 duǎn shì pín， rì cháng bào píng ān hěn fāng biàn。','Đúng rồi, còn gửi được ảnh, video ngắn nữa, báo bình an hàng ngày tiện lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_07','V601','阮明',7,'太好了，你教我一步步注册，今晚就能跟家里视频。','tài hǎo le， nǐ jiāo wǒ yí bù bù zhù cè， jīn wǎn jiù néng gēn jiā lǐ shì pín。','Tuyệt quá, cậu chỉ tớ đăng ký từng bước nhé, tối nay là gọi video về nhà được luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT602','SF1','宿舍WiFi卡顿，求助室友调试网络方便和家人打电话',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V602','SIT602','P1','twist','tuy_y',NULL,'高校宿舍晚八点至十点是网络使用高峰，多人同时联网会造成网速变慢、跨国视频卡顿。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_01','V602','阮明',1,'我一打开视频软件网络就卡顿，根本没法跟爸妈正常通话啊。','wǒ yī dǎ kāi shì pín ruǎn jiàn wǎng luò jiù kǎ dùn， gēn běn méi fǎ gēn bà mā zhèng cháng tōng huà a。','Tớ vừa mở phần mềm video lên là mạng giật lag ngay, chẳng thể nói chuyện đàng hoàng với bố mẹ được gì cả.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_02','V602','小林',2,'是不是宿舍同时好几个人连WiFi，带宽被占满了？','shì bú shì sù shè tóng shí hǎo jǐ gè rén lián WiFi， dài kuān bèi zhàn mǎn le？','Có phải trong ký túc xá cùng lúc mấy người kết nối WiFi, băng thông bị chiếm hết không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_03','V602','阮明',3,'刚才隔壁宿舍也在刷视频，我切换手机流量试试还是卡嘛。','gāng cái gé bì sù shè yě zài shuā shì pín， wǒ qiè huàn shǒu jī liú liàng shì shì hái shì kǎ ma。','Lúc nãy phòng bên cạnh cũng đang xem video, tớ chuyển sang dùng 4G thử vẫn giật.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_04','V602','小林',4,'我教你断开自动连接的多余设备，路由器重启一下会流畅很多。','wǒ jiāo nǐ duàn kāi zì dòng lián jiē de duō yú shè bèi， lù yóu qì zhòng qǐ yī xià huì liú chàng hěn duō。','Để tớ chỉ cậu ngắt bớt mấy thiết bị tự kết nối thừa, khởi động lại router thì sẽ mượt hơn nhiều đấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_05','V602','阮明',5,'重启路由器之后，跨国视频延迟能降低多少？','chóng qǐ lù yóu qì zhī hòu， kuà guó shì pín yán chí néng jiàng dī duō shǎo？','Khởi động lại router xong thì độ trễ video xuyên quốc gia giảm được bao nhiêu vậy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_06','V602','小林',6,'至少少一半卡顿，避开晚间八点上网高峰效果更好。','zhì shǎo shǎo yí bàn kǎ dùn， bì kāi wǎn jiān bā diǎn shàng wǎng gāo fēng xiào guǒ gèng hǎo。','Ít nhất giảm được một nửa tình trạng giật, tránh giờ cao điểm tám giờ tối thì càng tốt hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_07','V602','阮明',7,'我现在跟着你的步骤操作，等下再打视频电话。','wǒ xiàn zài gēn zhe nǐ de bù zhòu cāo zuò， děng xià zài dǎ shì pín diàn huà。','Giờ tớ làm theo các bước cậu chỉ nhé, lát nữa gọi video lại thử.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT603','SF1','时差冲突，错过和父母固定视频时间，重新约定时段',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V603','SIT603','P1','suon_se','tuy_y',NULL,'跨国跨时区留学生和家人一般会约定固定通话时间，临时无法上线必须提前留言报平安，避免家人过度担忧。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_01','V603','阮明',1,'昨天上课拖堂，错过了和爸妈约定的视频时间，他们一直等我。','zuó tiān shàng kè tuō táng， cuò guò le hé bà mā yuē dìng de shì pín shí jiān， tā men yì zhí děng wǒ。','Hôm qua học kéo dài quá giờ, tớ lỡ mất giờ video hẹn với bố mẹ, ông bà cứ chờ tớ mãi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_02','V603','苏雯',2,'越南和国内有一小时时差，你可以提前调整固定联络时段哦。','yuè nán hé guó nèi yǒu yī xiǎo shí shí chà， nǐ kě yǐ tí qián tiáo zhěng gù dìng lián luò shí duàn ó。','Việt Nam với trong nước lệch nhau một tiếng đó, cậu có thể điều chỉnh trước khung giờ liên lạc cố định mà.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_03','V603','阮明',3,'我这边晚上七点，越南就是傍晚六点，这个时间他们刚好下班。','wǒ zhè biān wǎn shàng qī diǎn， yuè nán jiù shì bàng wǎn liù diǎn， zhè ge shí jiān tā men gāng hǎo xià bān。','Bên tớ bảy giờ tối thì bên Việt Nam là sáu giờ chiều, đúng lúc bố mẹ vừa tan làm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_04','V603','苏雯',4,'那你跟家里重新敲定这个时间，提前发消息提醒他们上线吧。','nà nǐ gēn jiā lǐ chóng xīn qiāo dìng zhè ge shí jiān， tí qián fā xiāo xī tí xǐng tā men shàng xiàn ba。','Vậy cậu chốt lại giờ này với gia đình luôn đi, rồi nhắn tin nhắc trước cho họ lên mạng nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_05','V603','阮明',5,'我昨天临时缺场，爸妈还以为我出了什么事，特别担心。','wǒ zuó tiān lín shí quē chǎng， bà mā hái yǐ wéi wǒ chū le shén me shì， tè bié dān xīn。','Hôm qua tớ đột xuất vắng mặt, bố mẹ tưởng tớ xảy ra chuyện gì, lo lắng lắm luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_06','V603','苏雯',6,'下次如果有课，提前发文字留言告知家人，免得他们焦虑。','xià cì rú guǒ yǒu kè， tí qián fā wén zì liú yán gào zhī jiā rén， miǎn de tā men jiāo lǜ。','Lần sau nếu có lịch học thì nhắn tin báo trước cho gia đình biết, kẻo họ lo lắng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_07','V603','阮明',7,'我记下了，今晚提前跟家里敲定新的视频时段。','wǒ jì xià le， jīn wǎn tí qián gēn jiā lǐ qiāo dìng xīn de shì pín shí duàn。','Tớ ghi nhớ rồi, tối nay sẽ chốt trước giờ video mới với gia đình.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT604','SF1','软件登录失败、账号被锁，找同学帮忙找回账号',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V604','SIT604','P1','that_bai_nhe','tuy_y',NULL,'公共网络存在安全风险，跨国通讯软件检测到异地登录会自动锁号，保护用户隐私与账号安全。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_01','V604','阮明',1,'糟糕，我的视频软件账号提示异常登录，直接被系统锁住了。','zāo gāo， wǒ de shì pín ruǎn jiàn zhàng hào tí shì yì cháng dēng lù， zhí jiē bèi xì tǒng suǒ zhù le。','Chết rồi, tài khoản phần mềm video của tớ báo đăng nhập bất thường, bị hệ thống khóa luôn rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_02','V604','小林',2,'你是不是切换手机、频繁换WiFi登录，系统判定有风险？','nǐ shì bú shì qiè huàn shǒu jī、 pín fán huàn WiFi dēng lù， xì tǒng pàn dìng yǒu fēng xiǎn？','Có phải cậu đổi điện thoại, đổi WiFi đăng nhập liên tục nên hệ thống thấy có rủi ro không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_03','V604','阮明',3,'昨天去图书馆连公共网络登录过，之后回家就登不上去嘛。','zuó tiān qù tú shū guǎn lián gōng gòng wǎng luò dēng lù guò， zhī hòu huí jiā jiù dēng bù shàng qù ma。','Hôm qua tớ ra thư viện nối mạng công cộng để đăng nhập, xong về nhà là không vào được nữa luôn.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_04','V604','小林',4,'解锁需要邮箱收验证链接，你注册时绑定的邮箱还能正常使用吗？','jiě suǒ xū yào yóu xiāng shōu yàn zhèng liàn jiē， nǐ zhù cè shí bǎng dìng de yóu xiāng hái néng zhèng cháng shǐ yòng ma？','Mở khóa cần email nhận link xác nhận, email cậu đăng ký lúc trước còn dùng được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_05','V604','阮明',5,'邮箱密码我记混了，现在双重验证全部卡住没法操作。','yóu xiāng mì mǎ wǒ jì hùn le， xiàn zài shuāng chóng yàn zhèng quán bù kǎ zhù méi fǎ cāo zuò。','Mật khẩu email tớ nhớ nhầm mất rồi, giờ xác thực hai lớp bị kẹt hết không thao tác được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_06','V604','小林',6,'只能先找回邮箱密码，才能解锁通讯软件账号，一步一步来。','zhǐ néng xiān zhǎo huí yóu xiāng mì mǎ， cái néng jiě suǒ tōng xùn ruǎn jiàn zhàng hào， yí bù yí bù lái。','Chỉ còn cách lấy lại mật khẩu email trước, thì mới mở khóa được tài khoản phần mềm liên lạc, từ từ làm từng bước nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_07','V604','阮明',7,'麻烦你陪我操作，不然我今天完全联系不上家里人。','má fán nǐ péi wǒ cāo zuò， bù rán wǒ jīn tiān wán quán lián xì bù shàng jiā lǐ rén。','Phiền cậu ngồi cùng giúp tớ thao tác, không thì hôm nay tớ chẳng liên lạc được với gia đình chút nào.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT605','SF1','不会操作美颜、屏幕共享，请教室友教自己给家人展示校园',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V605','SIT605','P1','suon_se','tuy_y',NULL,'国际视频软件自带基础美颜、屏幕共享功能，留学生常用来实时展示校园、宿舍生活给海外亲人。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_01','V605','阮明',1,'我想给爸妈看看校园风景，不知道怎么打开屏幕共享功能啊。','wǒ xiǎng gěi bà mā kàn kàn xiào yuán fēng jǐng， bù zhī dào zěn me dǎ kāi píng mù gòng xiǎng gōng néng a。','Tớ muốn cho bố mẹ xem cảnh trường, mà không biết cách bật tính năng chia sẻ màn hình thế nào cả.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_02','V605','小林',2,'视频通话界面下方有分享按钮，点一下就能同步实景画面呢。','shì pín tōng huà jiè miàn xià fāng yǒu fēn xiǎng àn niǔ， diǎn yī xià jiù néng tóng bù shí jǐng huà miàn ne。','Ở phía dưới giao diện gọi video có nút chia sẻ đó, bấm vào là đồng bộ cảnh thực luôn ấy.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_03','V605','阮明',3,'另外画面光线不好，有没有简单的美颜提亮功能？','lìng wài huà miàn guāng xiàn bù hǎo， yǒu méi yǒu jiǎn dān de měi yán tí liàng gōng néng？','Với lại ánh sáng cảnh quay không đẹp lắm, có tính năng làm đẹp tăng sáng đơn giản nào không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_04','V605','小林',4,'侧边工具栏有基础提亮滤镜，不用复杂调整，一键开启就行。','cè biān gōng jù lán yǒu jī chǔ tí liàng lǜ jìng， bù yòng fù zá tiáo zhěng， yī jiàn kāi qǐ jiù xíng。','Ở thanh công cụ bên cạnh có bộ lọc tăng sáng cơ bản, không cần chỉnh phức tạp gì đâu, bấm một cái là bật liền.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_05','V605','阮明',5,'共享画面的时候，手机里的照片相册也能同步展示给家人吗？','gòng xiǎng huà miàn de shí hòu， shǒu jī lǐ de zhào piān xiàng cè yě néng tóng bù zhǎn shì gěi jiā rén ma？','Lúc chia sẻ màn hình thì kho ảnh trong điện thoại cũng đồng bộ cho gia đình xem được không?',NULL);
